    'SHS 2: Spreadsheets: logical and lookup functions' => [
        ['The IF function', ['adds numbers', 'finds the average', 'returns one value if a condition is true and another if it is false', 'sorts data'], 'C', '=IF(test, value_if_true, value_if_false).', 2],
