        ['FALSE as the last argument of VLOOKUP means', ['find an approximate match', 'ignore errors', 'sort the table', 'find an exact match'], 'D', 'Exact match.', 4],
        ['=AND(B2>=50, C2>=50) returns TRUE when', ['both B2 and C2 are 50 or more', 'either is 50 or more', 'neither is 50 or more', 'B2 is blank'], 'A', 'All conditions must be true.', 3],
        ['=OR(B2="Yes", C2="Yes") returns TRUE when', ['both are "No"', 'at least one cell is "Yes"', 'both are blank', 'never'], 'B', 'Any condition true.', 3],
        ['A nested IF is used to', ['join two sheets', 'make charts', 'test several conditions, such as grading A, B, C and F', 'print rows'], 'C', 'IF inside IF.', 4],
        ['RANK is used to', ['add a list', 'count blanks', 'find text', 'show the position of a value in a list'], 'D', 'For example class position.', 3],
