        ['=ROUND(3.456, 2) returns ___.', ['3.46'], '', 'Two decimal places.', 2, 'fill'],
        ['The symbol used to join text in Excel formulas is ___.', ['&', 'ampersand'], '', '=A1&B1.', 3, 'fill'],
        ['Marks are in B2:B41. Write formulas to find (a) how many pupils passed (50 or more), (b) the average of those who passed, and (c) "Pass" or "Fail" for the pupil in row 2.', ['COUNTIF', 'AVERAGEIF', 'IF'], '(a) =COUNTIF(B2:B41,">=50"). (b) =AVERAGEIF(B2:B41,">=50"). (c) =IF(B2>=50,"Pass","Fail").', 'Compare your answer with the model answer and tick off the points you made.', 3, 'theory', 6],
        ['Explain how VLOOKUP works using a table of item codes and prices as an example.', ['Lookup value', 'Table range', 'Column index', 'Exact match'], 'A price list has codes in F2:F20 and prices in G2:G20. =VLOOKUP(A2,$F$2:$G$20,2,FALSE) looks for the code in A2 in the first column of the table, and when an exact match is found it returns the value in the second column, the price.', 'Compare your answer with the model answer and tick off the points you made.', 3, 'theory', 6],
        ['Write a nested IF formula that converts a mark in C2 into grades: A1 (75+), B2 (70–74), C4 (60–69), C6 (50–59) and F9 (below 50).', ['Highest first', 'Correct bands', 'Correct nesting', 'F9 default'], '=IF(C2>=75,"A1",IF(C2>=70,"B2",IF(C2>=60,"C4",IF(C2>=50,"C6","F9"))))', 'Compare your answer with the model answer and tick off the points you made.', 3, 'theory', 6],
        ['Differentiate between COUNT, COUNTA and COUNTIF.', ['COUNT', 'COUNTA', 'COUNTIF'], 'COUNT counts cells that contain numbers. COUNTA counts all cells that are not empty, including text. COUNTIF counts cells in a range that meet a given condition, for example ">=50".', 'Compare your answer with the model answer and tick off the points you made.', 3, 'theory', 6],
        ['A sheet has first names in A2 and surnames in B2. Write a formula to show the full name in C2 and one to show the surname in capital letters.', ['Join with space', 'UPPER function'], 'Full name: =A2&" "&B2 (or =CONCAT(A2," ",B2)). Surname in capitals: =UPPER(B2).', 'Compare your answer with the model answer and tick off the points you made.', 3, 'theory', 4],
        ['Explain how the RANK function can be used to produce class positions and one problem with ties.', ['RANK formula', 'Absolute range', 'Tie behaviour'], '=RANK(B2,$B$2:$B$41) gives the position of the mark in B2 among all marks, 1 for the highest. Pupils with equal marks get the same rank and the next rank is skipped, for example two pupils at 3rd means no 4th.', 'Compare your answer with the model answer and tick off the points you made.', 3, 'theory', 4],
